// GRIMGE Prototype — pixel-art FX / prop sprite sheets.
//
// Sheets are generated by art/authoring/generate_fx_sprites.cjs (editable
// .aseprite sources in art/authoring/fx/). Each sheet is a horizontal strip
// of equally sized frames; frames are drawn with smoothing disabled so the
// pixels stay crisp at any integer scale.

export const FX_SHEETS = Object.freeze({
  fx_flame: { w: 16, h: 24, frames: 6 },
  fx_lightning: { w: 32, h: 128, frames: 5 },
  fx_spark: { w: 16, h: 16, frames: 4 },
  fx_splash: { w: 40, h: 24, frames: 6 },
  fx_ice: { w: 32, h: 32, frames: 5 },
  fx_lava_bubble: { w: 12, h: 12, frames: 6 },
  fx_smoke: { w: 32, h: 32, frames: 6 },
  prop_crate: { w: 32, h: 32, frames: 3 },
  prop_barrel: { w: 24, h: 32, frames: 3 },
  fx_weather: { w: 8, h: 8, frames: 8 },
  fx_rubble: { w: 12, h: 10, frames: 4 }
});

const images = {};

export function loadFxSprites() {
  if (typeof globalThis.Image !== 'function') return Promise.resolve(false);
  return Promise.all(Object.keys(FX_SHEETS).map((name) => new Promise((resolve) => {
    const image = new Image();
    image.onload = () => { images[name] = image; resolve(true); };
    image.onerror = () => resolve(false);
    image.src = `assets/sprites/fx/${name}.png`;
  })));
}

export function fxReady(name) { return !!images[name]; }

// Draw one frame. anchor: 'bottom' (feet on y) or 'center'.
export function drawFx(ctx, name, frame, x, y, { scale = 2, anchor = 'bottom', alpha = 1, flip = false } = {}) {
  const sheet = FX_SHEETS[name];
  const image = images[name];
  if (!sheet || !image) return false;
  const f = ((Math.floor(frame) % sheet.frames) + sheet.frames) % sheet.frames;
  const w = sheet.w * scale; const h = sheet.h * scale;
  const dx = Math.round(x - w / 2);
  const dy = Math.round(anchor === 'bottom' ? y - h : y - h / 2);
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  if (alpha < 1) ctx.globalAlpha *= Math.max(0, alpha);
  if (flip) { ctx.translate(dx + w, dy); ctx.scale(-1, 1); ctx.drawImage(image, f * sheet.w, 0, sheet.w, sheet.h, 0, 0, w, h); }
  else ctx.drawImage(image, f * sheet.w, 0, sheet.w, sheet.h, dx, dy, w, h);
  ctx.restore();
  return true;
}
